  (md5('country-Belarus')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Belarus', '🇧🇾', 'Europe', 'UMMV', 'Belarus CAA', 'restricted', '3 working days', 'slow', ARRAY['Fax']::text[], NULL, NULL, NULL, 'Surcharge if notice < 3 days', 'Southern FIR closed (Ukraine border). Most Western operators avoid Belarus.', 'warn', '2026-09-08'),
  (md5('country-Bulgaria')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Bulgaria', '🇧🇬', 'Europe', 'LBSR', 'CAA Bulgaria', 'required', '48 h', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter: permit required — national CAA. MEDEVAC: EXEMPT. Slot: check WASG for L2/L3 airports. PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
  (md5('country-France')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'France', '🇫🇷', 'Europe', 'LFFF/LFRR', 'DSNA / DGAC', 'conditional', 'Charter: 48–72 h | Private: n/a', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight (non-commercial): EXEMPT — Chicago Conv. Art.5 + EU Reg 1008/2008. No overflight/landing permit required. | Charter flight (commercial non-scheduled): DGAC PERMIT REQUIRED via SAGA portal or email — lead time 48–72h. Legal basis: French Civil Aviation Code Art. D.131-1. | MEDEVAC/Humanitarian: EXEMPT (Art.5) — recommended to inform DGAC. | WASG Slots: CDG/ORY/NCE/FSC = Level 3 (MANDATORY) via LYS/NCY/NTE/CMF = Level 2. | PPR: check AIP AD 2.20 per airport (CDG/ORY = no PPR, smaller aerodromes = PPR required).', 'none', '2026-09-08'),
  (md5('country-Germany')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Germany', '🇩🇪', 'Europe', 'EDGG/EDWW', 'Luftfahrt-Bundesamt (LBA)', 'conditional', '48–72 h', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter: permit required — LBA — MEDEVAC: EXEMPT. Slots: FRA/MUC/DUS/TXL/HAM Level 3 via Flughafenkoordination Deutschland (FKD).', 'none', '2026-09-08'),
  (md5('country-Greece')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Greece', '🇬🇷', 'Europe', 'LGGG', 'HCAA Hellenic CAA', 'required', '5 working days', 'slow', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU). Charter: permit required — HCAA. Slot: ATH Level 3.', 'warn', '2026-09-08'),
