  (md5('country-Norway')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Norway', '🇳🇴', 'Europe', 'ENOR/ENOB', 'Luftfartstilsynet (CAA Norway)', 'required', '48–72 h', 'med', '{}', NULL, NULL, NULL, NULL, 'FIR Norway (ENOR) + Bodø Oceanic (ENOB). Non-EEA operators: permit required. See AIP Norway for specific airports.', 'none', '2026-09-08'),
  (md5('country-Netherlands')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Netherlands', '🇳🇱', 'Europe', 'EHAA', 'ILT — Inspectie Leefomgeving en Transport', 'conditional', 'Charter: 48–72 h | Private: n/a', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter non-EU: permit required — ILT required. MEDEVAC: EXEMPT. Slot: AMS (Schiphol) = Level 3 — PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
  (md5('country-Belgium')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Belgium', '🇧🇪', 'Europe', 'EBBU', 'SPF Mobilité et Transports — DGTA', 'conditional', 'Charter: 48–72 h | Private: n/a', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter non-EU: permit required — DGTA required. MEDEVAC: EXEMPT. Slot: BRU = Level 3 via Brussels Airport Coordination. PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
  (md5('country-Portugal')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Portugal', '🇵🇹', 'Europe', 'LPPC/LPPO', 'ANAC — Autoridade Nacional da Aviação Civil', 'conditional', 'Charter: 48–72 h | Private: n/a', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter non-EU: permit required — ANAC required. Slot: LIS/OPO = Level 3 via ANA Aeroportos. PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
  (md5('country-Sweden')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Sweden', '🇸🇪', 'Europe', 'ESAA', 'Transportstyrelsen — Swedish Transport Agency', 'conditional', 'Charter: 48–72 h | Private: n/a', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter non-EU: permit required — Transportstyrelsen required. Slot: ARN = Level 3 via SWECOS. PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
