  (md5('country-Denmark')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Denmark', '🇩🇰', 'Europe', 'EKDK', 'Trafikstyrelsen — Danish Transport Authority', 'conditional', 'Charter: 48–72 h | Private: n/a', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter non-EU: permit required — Trafikstyrelsen required. Slot: CPH = Level 3. PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
  (md5('country-Ireland')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Ireland', '🇮🇪', 'Europe', 'EISN', 'Irish Aviation Authority — IAA', 'conditional', 'Charter: 48–72 h | Private: n/a', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter non-EU: permit required — IAA required. Slot: DUB = Level 3. PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
  (md5('country-Malta')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Malta', '🇲🇹', 'Europe', 'LMMM', 'Transport Malta — Civil Aviation Directorate (CAD), Duty Management Office (DMO)', 'conditional', 'EU/EEA carriers: prior notification | Non-EEA / non-Community operators: permit required, apply ahead | Non-standard C of A or Permit to Fly: 72h', 'med', '{}', NULL, NULL, NULL, 'No CAA processing fee for overflight; Eurocontrol route charges apply separately.', 'EU/EASA-registered aircraft (valid EASA Form 20a where applicable): no overflight permit needed for intra-EU/EEA routes, but PRIOR NOTIFICATION to the DMO is still required. Flights by Community carriers outside the EEA (EU+Iceland+Liechtenstein+Norway), and all flights by non-Community operators, require prior approval/operating permit from the DMO. STS/ATFMEXEMPTAPPROVED flight plan insertions need DMO approval ≥2h before EOBT. Foreign aircraft holding a non-standard C of A or a Permit to Fly must apply ≥72h in advance. Single international airport: Malta Intl (LMML/MLA) — WASG-coordinated, check current level. Contact: DMO, Malta Transport Centre, Triq Pantar, Lija LJA2021 .', 'none', '2026-09-08'),
  (md5('country-Romania')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Romania', '🇷🇴', 'Europe', 'LRBB', 'AACR Autoritatea Aeronautică Civilă Română', 'required', '48–72 h', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU Reg 1008/2008 + Chicago Art.5). Charter: permit required — national CAA. MEDEVAC: EXEMPT. Slot: check WASG for L2/L3 airports. PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
  (md5('country-Russia')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Russia', '🇷🇺', 'Europe', 'UUUU', 'Rosaviatsiya (FATA)', 'closed', 'N/A', 'na', ARRAY['—']::text[], NULL, NULL, NULL, NULL, 'Closed to Western operators since March 2022. No access for EU/UK/US/Canada/Switzerland/Norway operators.', 'danger', '2026-09-08'),
  (md5('country-Spain')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Spain', '🇪🇸', 'Europe', 'LECM/GCCC', 'AESA Agencia Estatal de Seguridad Aérea', 'conditional', '48–72 h', 'med', '{}', NULL, NULL, NULL, NULL, 'Private flight: EXEMPT (EU/Chicago Art.5). Charter flight: AESA permit required via Slots: MAD/BCN Level 3 via Aena Slots. PPR: check AIP AD 2.20.', 'none', '2026-09-08'),
  (md5('country-Switzerland')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Switzerland', '🇨🇭', 'Europe', 'LSAS', 'OFAC / BAZL Swiss Federal Office of Civil Aviation', 'conditional', '48–72 h', 'med', '{}', NULL, NULL, NULL, NULL, 'EU operators treated as EASA equivalent. Non-EASA: charter permit required.', 'none', '2026-09-08'),
  (md5('country-Turkey')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Turkey', '🇹🇷', 'Europe', 'LTAA', 'DGCA Turkey (SHGM)', 'required', '48 h', 'med', '{}', NULL, NULL, NULL, 'Aucun frais CAA. Navigation via Eurocontrol', 'Permit valid -24h/+72h. ASA signed with ~161 countries (source: official SHGM): overflight without permit for these countries. Countries outside ASA: required permits 48h. Cargo to Libya/Iraq/Syria/Armenia/Cyprus: permit even with ASA. Private GA (owner = operator, max 12 pax): exempt from permit. Commercial charter: landing permit + AOC required.', 'none', '2026-09-08'),
  (md5('country-Ukraine')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Ukraine', '🇺🇦', 'Europe', 'UKBV/UKOV', 'SSSU / UkSATSE', 'closed', 'N/A', 'na', ARRAY['—']::text[], NULL, NULL, NULL, NULL, 'Closed since 24 February 2022. Indefinite NOTAM closure. No civil flights permitted.', 'danger', '2026-09-08'),
  (md5('country-United Kingdom')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'United Kingdom', '🇬🇧', 'Europe', 'EGTT/EGPX', 'UK CAA – Civil Aviation Authority', 'required', '3 working days', 'slow', '{}', NULL, NULL, NULL, NULL, 'Private/non-commercial flight (all registrations): Chicago Art.5 — permit exempt. | Charter/NS non-EASA non-UK operator: FCP REQUIRED — 48 working days minimum via UK CAA . | Charter EASA operator (EU/EEA): generally FCP exempt — confirm with UK CAA. | State flight (non-UK): FCP + diplomatic authorisation 7–14 days. | GAR UK Border Force: MANDATORY ALL GA flights 24h before (criminal offence). Source: ANO 2016 + TNP SOP §9.11.2-9.11.3.', 'none', '2026-09-08'),
  (md5('country-Algeria')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Algeria', '🇩🇿', 'Africa', 'DAAA', 'ANAC Algeria', 'required', '3–7 working days', 'vlong', ARRAY['Local agent']::text[], NULL, NULL, NULL, NULL, 'Mutual ban with Morocco (April 2025). AFTN + local agent. French/Arabic docs recommended.', 'warn', '2026-09-08'),
  (md5('country-Cameroon')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Cameroon', '🇨🇲', 'Africa', 'FKKK', 'CCAA Cameroon', 'required', '7 working days', 'vlong', ARRAY['Local agent']::text[], NULL, NULL, NULL, NULL, 'Ministry of Defence approval required. Local agent strongly recommended.', 'warn', '2026-09-08'),
  (md5('country-Congo (Brazzaville)')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Congo (Brazzaville)', '🇨🇬', 'Africa', 'FCCC', 'ANAC Congo', 'required', '48–72 h', 'med', ARRAY['Local agent']::text[], NULL, NULL, NULL, 'No official fees', 'No official processing fees — confirm with local agent.', 'none', '2026-09-08'),
