  (md5('country-Djibouti')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Djibouti', '🇩🇯', 'Africa', 'HDDD', 'ANAC Djibouti', 'required', '48–72 h', 'med', ARRAY['Local agent']::text[], NULL, NULL, NULL, NULL, 'Single point of failure — one person issues permits Mon–Fri only.', 'warn', '2026-09-08'),
  (md5('country-DRC (Congo Kinshasa)')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'DRC (Congo Kinshasa)', '🇨🇩', 'Africa', 'FZZA', 'RVA – Air Routes Authority', 'required', '5+ working days', 'vlong', ARRAY['Local agent (mandatory)']::text[], NULL, NULL, NULL, NULL, '5 working days = ''short notice''. Specialist local agent essential.', 'warn', '2026-09-08'),
  (md5('country-Egypt')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Egypt', '🇪🇬', 'Africa', 'HECC', 'ECAA Egyptian CAA', 'required', '24–48 h', 'med', '{}', NULL, NULL, NULL, NULL, 'Strict route requirements. Verify routing before submission.', 'none', '2026-09-08'),
  (md5('country-Ethiopia')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Ethiopia', '🇪🇹', 'Africa', 'HAAA', 'ECAA Ethiopian CAA', 'required', '1–3 working days', 'fast', '{}', NULL, NULL, NULL, NULL, 'Fastest processing in East Africa. Humanitarian exemptions available.', 'none', '2026-09-08'),
  (md5('country-Gabon')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Gabon', '🇬🇦', 'Africa', 'FOOL', 'ANAC Gabon (DGAC)', 'required', '48 h', 'med', ARRAY['Local agent']::text[], NULL, NULL, NULL, 'USD 275 wire transfer before issuance', 'USD 275 mandatory wire transfer to CAA account before permit is issued.', 'warn', '2026-09-08'),
  (md5('country-Ghana')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Ghana', '🇬🇭', 'Africa', 'DGAC', 'GCAA Ghana CAA', 'required', '24–48 h', 'med', '{}', NULL, NULL, NULL, NULL, 'Straightforward process. Generally smooth within ECOWAS.', 'none', '2026-09-08'),
  (md5('country-Guinea-Bissau')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Guinea-Bissau', '🇬🇼', 'Africa', 'GGGG', 'IACEP', 'required', '7 working days', 'vlong', ARRAY['Local agent']::text[], NULL, NULL, NULL, NULL, 'One of the longest notice periods in West Africa.', 'warn', '2026-09-08'),
  (md5('country-Kenya')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Kenya', '🇰🇪', 'Africa', 'HKNA', 'KCAA Kenya CAA', 'required', '48 h', 'med', '{}', NULL, NULL, NULL, NULL, 'Online portal only. Closed weekends, no back-up. File before Thursday for weekend flights.', 'warn', '2026-09-08'),
  (md5('country-Libya')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Libya', '🇱🇾', 'Africa', 'HLLL', 'LYCAA — Libyan Civil Aviation Authority', 'restricted', 'N/A', 'na', ARRAY['Local agent only']::text[], NULL, NULL, NULL, NULL, 'Highly unstable airspace. EASA CZIB-2017-02R20: do not operate (EU/UK operators only). FAA SFAR, UK FCO: total ban. Non-EASA/non-US/non-UK operators: possible via local agent with full ATC Tripoli coordination + approach from the sea for coastal areas. Militias present — risk of interception.', 'danger', '2026-09-08'),
  (md5('country-Morocco')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Morocco', '🇲🇦', 'Africa', 'GMMM', 'ANAC Morocco', 'required', '3–7 working days', 'vlong', '{}', NULL, NULL, NULL, NULL, 'AFTN ONLY — no email, no fax. ATC not required to speak English. French/Arabic docs essential.', 'warn', '2026-09-08'),
