  (md5('country-Senegal')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Senegal', '🇸🇳', 'Africa', 'GOOO', 'ANACIM', 'required', '2–5 working days', 'med', '{}', NULL, NULL, NULL, NULL, 'ASECNA zone. Free Route Airspace from FL250+. Mauritania routing available.', 'none', '2026-09-08'),
  (md5('country-Somalia')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Somalia', '🇸🇴', 'Africa', 'HCSM', 'SCAA Somali CAA', 'restricted', '—', 'na', ARRAY['Local agent']::text[], NULL, NULL, NULL, NULL, 'US prohibits flights below FL260. False ATC units in northern FIR. Verify via CPDLC/SATCOM only.', 'danger', '2026-09-08'),
