  (md5('country-Sudan')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Sudan', '🇸🇩', 'Africa', 'HSSS', 'SCAA Sudan CAA', 'required', '48 h', 'med', ARRAY['Local agent']::text[], NULL, NULL, NULL, NULL, 'Active conflict since 2023. HSSK/Khartoum closed. Verify NOTAMs before filing.', 'warn', '2026-09-08'),
