  (md5('country-Tunisia')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Tunisia', '🇹🇳', 'Africa', 'DTTC', 'OACA Office Aviation Civile Aéroports', 'required', '3–5 working days', 'slow', '{}', NULL, NULL, NULL, NULL, 'Smoother than regional neighbours. French/Arabic docs recommended.', 'none', '2026-09-08'),
  (md5('country-Zimbabwe')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Zimbabwe', '🇿🇼', 'Africa', 'FVHF', 'CAAZ Civil Aviation Authority Zimbabwe', 'required', '1–4 working days', 'fast', '{}', NULL, NULL, NULL, NULL, 'SADC compliance. Generally reasonable lead times.', 'none', '2026-09-08'),
  (md5('country-Bahrain')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Bahrain', '🇧🇭', 'Middle East', 'OBBB', 'CAAB – Civil Aviation Affairs', 'required', '24–48 h', 'med', '{}', NULL, NULL, NULL, NULL, 'EASA CZIB active. Fixed entry/exit corridors. Permit mandatory even for overflight.', 'warn', '2026-09-08'),
  (md5('country-Iran')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Iran', '🇮🇷', 'Middle East', 'OIIX/OIKK', 'CAO Iran', 'closed', 'N/A', 'na', ARRAY['—']::text[], NULL, NULL, NULL, NULL, 'EASA CZIB active. Tehran (OIIX) + Esfahan (OIKK) FIRs. Eastern FIR partly open above FL285. Western FIR closed. High risk of air defence misidentification.', 'danger', '2026-09-08'),
  (md5('country-Iraq')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Iraq', '🇮🇶', 'Middle East', 'ORBB', 'ICAA — Iraqi Civil Aviation Authority', 'conditional', '24–72 h', 'med', '{}', NULL, NULL, NULL, 'USD 375 (overflight) · USD 800+ (landing)', 'EASA (opérateurs UE/UK/ECAA) — CZIB-2026-05 (08/07/2026, remplace 2017-04R19 désormais retiré) : ne pas opérer dans le FIR Bagdad, tous FL, tant que le bulletin est actif (IBMGs, MANPADS). Au-dessus FL320 : autorisé avec risk assessment. France F0993/26 : airways M860/L602/L718 ou UM688 seulement, FL320+. Italie E0564/26 : éviter tout ORBB. Non-EASA : ouvert, permis ICAA obligatoire 72h (sans certificat ICAA) ou 24h (avec). NOTAM A0195/26 : GPS jamming/spoofing nord Irak.', 'warn', '2026-09-08'),
  (md5('country-Israel')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Israel', '🇮🇱', 'Middle East', 'LLLL', 'CAAI – Civil Aviation Authority Israel', 'restricted', '4 working days', 'slow', '{}', NULL, NULL, NULL, NULL, 'EASA CZIB active. FIR closed March 2026. Israeli passport stamp disqualifies crew/pax from most ME countries.', 'danger', '2026-09-08'),
  (md5('country-Jordan')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Jordan', '🇯🇴', 'Middle East', 'OJAC', 'CARC Civil Aviation Regulatory Commission', 'required', '24–48 h', 'med', '{}', NULL, NULL, NULL, NULL, 'EASA CZIB active. Verify current NOTAM status before filing.', 'warn', '2026-09-08'),
  (md5('country-Kuwait')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Kuwait', '🇰🇼', 'Middle East', 'OKAC', 'DGCA Kuwait', 'restricted', '24–48 h', 'med', ARRAY['Local agent']::text[], NULL, NULL, NULL, NULL, 'EASA CZIB active. Reopened in phases with fixed corridors.', 'danger', '2026-09-08'),
  (md5('country-Lebanon')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Lebanon', '🇱🇧', 'Middle East', 'OLBB', 'DGCA Lebanon', 'restricted', '—', 'na', ARRAY['Local agent']::text[], NULL, NULL, NULL, 'Overflight charges (LBP-based)', 'EASA CZIB active. Check NOTAMs before any consideration.', 'danger', '2026-09-08'),
