  (md5('country-Singapore')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Singapore', '🇸🇬', 'Asia', 'WSSS', 'CAAS Civil Aviation Authority Singapore', 'required', '2–3 working days', 'fast', '{}', NULL, NULL, NULL, 'Navigation charges via CAAS', 'Highly efficient processing. Permit required for non-scheduled ops. One of the most streamlined in Asia.', 'none', '2026-09-08'),
  (md5('country-South Korea')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'South Korea', '🇰🇷', 'Asia', 'RKRR', 'MOLIT / AAAK', 'required', '3 working days', 'slow', '{}', NULL, NULL, NULL, 'Overflight charges apply', 'Cruise speed restrictions in Incheon FIR. Route FIR info required. Coordination with AAAK (ATC agency) needed.', 'none', '2026-09-08'),
  (md5('country-Sri Lanka')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Sri Lanka', '🇱🇰', 'Asia', 'VCCF', 'CAASL Civil Aviation Authority Sri Lanka', 'required', '48 h', 'med', '{}', NULL, NULL, NULL, 'Overflight navigation charges', 'Route FIR information required. Submit full ICAO documents. Generally smooth processing.', 'none', '2026-09-08'),
  (md5('country-Taiwan')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Taiwan', '🇹🇼', 'Asia', 'RCTP', 'CAA Taiwan', 'required', '3 working days', 'slow', '{}', NULL, NULL, NULL, 'Overflight charges', 'Geopolitical sensitivity — China/Taiwan relations. Operators must declare correctly in FPL. Approved airways only.', 'warn', '2026-09-08'),
  (md5('country-Thailand')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Thailand', '🇹🇭', 'Asia', 'VTBB', 'CAAT Civil Aviation Authority Thailand', 'required', '48–72 h', 'med', '{}', NULL, NULL, NULL, 'Navigation bill direct to operator', 'Permit mandatory. CAAT issues navigation bill directly. Permit number in Item 18 of FPL.', 'none', '2026-09-08'),
  (md5('country-Uzbekistan')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Uzbekistan', '🇺🇿', 'Asia', 'UTAA', 'CAA Uzbekistan', 'required', '3 working days', 'slow', '{}', NULL, NULL, NULL, 'Navigation charges apply', 'Strategic transcontinental route. Route FIR info required. Generally accessible for non-scheduled operations.', 'none', '2026-09-08'),
  (md5('country-United States')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'United States', '🇺🇸', 'Americas', 'KZNY KZLA KZAU KZHU KZAB KZAK KZOA PAZA', 'FAA / CBP U.S. Customs and Border Protection', 'exempt', 'CBP eAPIS: 60 min before departure', 'fast', '{}', NULL, NULL, NULL, 'No overflight permit.', 'No overflight or landing permit required. CBP eAPIS PROCEDURE MANDATORY: submit crew/passenger list 60 min before departure via CBP eAPIS portal or eAPIS File. Private aircraft: ACAS procedure required. eTA not required for nationals of exempt countries. Customs declaration on arrival. FPL via NASSTATUS. WASG SLOTS (coordination required): EWR/Newark (L2), IAD/Washington Dulles International Airport (L2), JFK/New York-J.F. Kennedy (L3), LAX/Los Angeles (L2), MCO/Orlando (L2), ORD/Chicago-O'' Hare (L2), SAN/San Diego International Airport (L2), SEA/Seattle-Tacoma International Airport (L2), SFO/San Francisco (L2). FAA slot contacts: JFK: EWR: LAX: SFO: MCO: SEA: ', 'none', '2026-09-08'),
  (md5('country-Canada')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Canada', '🇨🇦', 'Americas', 'CZEG CZVR CZWG CZYZ CZUL CZQX CZQM', 'Transport Canada / CBSA — Agence des services frontaliers du Canada', 'exempt', 'CANPASS: 2h before entering airspace', 'fast', '{}', NULL, NULL, NULL, 'No overflight permit required.', 'No overflight or landing permit required (bilateral exemption). CANPASS-AIR PROCEDURE MANDATORY: 2h notice to CBSA before entry for private/charter aircraft. eTA required for eligible foreign nationals (except US nationals). FPL filed with NAV CANADA. Designated CBSA entry point mandatory (list at cbsa-asfc.gc.ca). NEXUS program accepted for US private aircraft. Slots YYZ/YVR/YUL/YYC/YTZ per WASG.', 'none', '2026-09-08'),
  (md5('country-Mexico')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Mexico', '🇲🇽', 'Americas', 'MMFR MMID MMZT MMMX MMMM', 'AFAC — Agencia Federal de Aviación Civil', 'required', '24–48 h', 'med', '{}', NULL, NULL, NULL, 'Permit required for non-scheduled flights.', 'AFAC permit mandatory for all charter/non-scheduled flights. Filing via AFAC portal or email. Documents: AOC, CofA, CofR, insurance, crew/passenger list, FPL. Minimum lead time 24h (48h recommended). Slots MEX/CUN/GDL per WASG.', 'none', '2026-09-08'),
  (md5('country-Cuba')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Cuba', '🇨🇺', 'Americas', 'MUHA', 'IACC — Instituto de Aeronáutica Civil de Cuba', 'required', '72 h', 'slow', '{}', NULL, NULL, NULL, 'Permit required + overflight fees.', 'Permit mandatory 72h in advance for all operators. Strict overflight of authorized corridors. US operators: OFAC restrictions — special US Treasury Department permit required. AFTN: MUHAZQZX. Slots HAV/VRA per WASG.', 'warn', '2026-09-08'),
  (md5('country-Argentina')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Argentina', '🇦🇷', 'Americas', 'SAEF SAMF SARR SAVF SAZF', 'ANAC — Administración Nacional de Aviación Civil', 'required', '48–72 h', 'med', '{}', NULL, NULL, NULL, 'No CAA fees. Fees ATC applicables.', 'Permit required by email ONLY. Main email: CC: ; ; ATC coordination: Documents: AOC, CofA, CofR, insurance, crew list.', 'none', '2026-09-08'),
  (md5('country-Brazil')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Brazil', '🇧🇷', 'Americas', 'SBBS SBCW SBRE SBAZ', 'ANAC — Agência Nacional de Aviação Civil', 'required', '72 h', 'slow', ARRAY['Agent (Lider)']::text[], NULL, NULL, NULL, 'Permit required. Agent recommended.', 'Permit mandatory for non-scheduled flights. TNP uses agent LIDER Aviation: /17/18. Minimum lead time 72h. Documents: AOC, CofA, CofR, insurance, GENDEC, passenger list. Slots GRU/CGH/SDU per WASG.', 'none', '2026-09-08'),
  (md5('country-Colombia')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Colombia', '🇨🇴', 'Americas', 'SKEC', 'Aerocivil — Unidad Administrativa Especial de Aeronáutica Civil', 'required', '24–48 h', 'med', '{}', NULL, NULL, NULL, 'Fees de navigation applicables.', 'Permit via Aerocivil portal or email. Standard ICAO documents. Slot BOG per WASG.', 'none', '2026-09-08'),
  (md5('country-Peru')::uuid, 'refdata', 'NetPlus RFP annexe A4 — prototype iteration 33', 'Peru', '🇵🇪', 'Americas', 'SPIM', 'DGAC — Dirección General de Aeronáutica Civil del Peru', 'required', '24–48 h', 'med', '{}', NULL, NULL, NULL, 'Fees de navigation applicables.', 'Permit required. Email: Application form required. Documents: AOC, CofA, CofR, insurance, FPL, crew/passenger list. Slot LIM per WASG.', 'none', '2026-09-08'),
